      {%- endcapture -%}

      {%- assign tokenHeader = tokenHeaderRaw | base64_url_safe_encode | replace: '=', '' -%}

      {%- capture tokenContentRaw -%}
        {"iss": {{- "snowdevil.ca" | json -}}
        ,"sub": {{- 1234 | json -}}
        ,"iat": "0"
        ,"exp": "0"
